# SPDX-License-Identifier: AGPL-3.0-only
import re
from functools import lru_cache

def solve(payload):
    pattern = payload['pattern'].split('/') if payload['pattern'] else []
    def one(path):
        parts = path.split('/') if path else []
        @lru_cache(None)
        def matches(i, j):
            if i == len(pattern):
                return j == len(parts)
            if pattern[i] == '**':
                return j < len(parts) and (matches(i + 1, j + 1) or matches(i, j + 1))
            if j == len(parts):
                return False
            regex = re.escape(pattern[i]).replace(r'\*', '.*').replace(r'\?', '.')
            return re.fullmatch(regex, parts[j], flags=re.DOTALL) is not None and matches(i + 1, j + 1)
        return matches(0, 0)
    return [one(path) for path in payload['paths']]

